mapper.select:
SELECT COUNT(*) FROM comment
WHERE post_id = #{postId} AND parent_id = 0
AND status = #{status}

SELECT c.id, c.post_id, c.parent_id, c.user_id, c.content, COALESCE(u.nickname, c.nickname) AS nickname, c.email, c.website, COALESCE(u.avatar, c.avatar) AS avatar, c.status, c.create_time FROM comment c LEFT JOIN `user` u ON u.id = c.user_id WHERE c.status = 1 AND c.parent_id IN
#{id}
ORDER BY c.create_time ASC

SELECT c.id, c.post_id, c.parent_id, c.user_id, c.content, COALESCE(u.nickname, c.nickname) AS nickname, c.email, c.website, COALESCE(u.avatar, c.avatar) AS avatar, c.status, c.create_time FROM comment c LEFT JOIN `user` u ON u.id = c.user_id
AND c.status = #{status}
ORDER BY c.create_time DESC
